INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (90251,0,0,'Of course, Highlord. I will speak my mind. The path of light is righteous and just. Whatever our means, let them remain virtuous.',12,0,100.0,1,0,68308,114977,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (90251,1,0,'The portal at Felblaze Ingress must be destroyed. With your permission, Highlord, Arator and I will deal with this.',12,0,100.0,1,0,68326,119266,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (90251,2,0,'The Light will guide my hand, Highlord.',12,0,100.0,2,0,69655,120616,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (90259,0,0,'It will be dangerous, but we may never get such a chance again. It may be the only way.',12,0,100.0,1,0,69002,120189,0,'LegionCore');
