INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (91866,1,0,'We must stand together against the coming darkness. We must cast aside the shackles of race and kingdom. We must unite as one!',14,0,100.0,0,0,0,98559,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (91866,2,0,'On this day, the Order of the Silver Hand is reborn! Together, Sargeras himself shall shudder at our might!',14,0,100.0,0,0,0,94428,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (91866,3,0,'Place the blade on the altar when you are ready. The Light will be our forge.',12,0,100.0,0,0,0,98745,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (92149,0,0,'Do you think I\'ll be picked to go on the next mission outing? I heard that the Highlord lets you keep some of the spoils!',12,0,100.0,0,0,0,94447,0,'LegionCore');
