INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106337,0,0,'My brother spoke of a dragon called Lanigosa at Wyrmrest Temple. Seek her out while I prepare a strike force for the tomb.',12,0,100.0,0,0,0,111582,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106337,1,0,'You can make your way there through the portal to Dalaran Crater. I will meet you there with additional forces.',12,0,100.0,0,0,0,109411,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106337,2,0,'Efrina, find your brother and rally at the tomb.',12,0,100.0,0,0,0,109419,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106347,0,0,'No more challengers! Disturb these kings no more!',12,0,100.0,0,0,0,114409,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106370,0,0,'%s falls to one knee, gravely wounded.',16,0,100.0,0,0,0,109484,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106370,1,0,'%s is |cFFFF0404|Hspell:204237|h[Gravely Wounded]|h|r and cannot fight until healed!',41,0,100.0,0,0,0,109485,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106371,0,0,'%s falls to one knee, gravely wounded.',16,0,100.0,0,0,0,109484,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106371,1,0,'%s is |cFFFF0404|Hspell:204237|h[Gravely Wounded]|h|r and cannot fight until healed!',41,0,100.0,0,0,0,109485,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,0,0,'Ah, there you are. The area was secured at great cost. This cannot continue, we must retrieve the Silver Hand and destroy the entrance to the tomb.',12,0,100.0,0,0,0,109479,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,1,0,'I will complete the ritual to release the Hammer and collapse the tomb, but we must be quick. I can sense evil emanating from the tomb.',12,0,100.0,0,0,0,109480,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,2,0,'You and I shall lead a small team in first. Let me know when you are ready.',12,0,100.0,0,0,0,109481,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,3,0,'Just a brief swim and we\'ll reach the tomb.',12,0,100.0,0,0,0,109570,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,4,0,'Behold the Tomb of Tyr, built by the mighty... wait! These monsters dare befoul the tomb?!',12,0,100.0,0,0,0,109571,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,5,0,'This cannot stand! Destroy these abominations!',12,0,100.0,0,0,0,109572,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,6,0,'It pains me to see such destruction threaten the resting place of the Silver Hand.',12,0,100.0,0,0,0,109575,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,7,0,'Look there! The sacred hammer\'s wards remain strong! First we must purge this infestation. Let me know when you are ready.',12,0,100.0,0,0,0,109839,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,8,0,'Watch yourselves! Let us cleanse this chamber!',12,0,100.0,0,0,0,109893,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,9,0,'%s falls to one knee, gravely wounded.',16,0,100.0,0,0,0,109484,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,10,0,'%s is |cFFFF0404|Hspell:204237|h[Gravely Wounded]|h|r and cannot fight until healed!',41,0,100.0,0,0,0,109485,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,17,0,'Well done everyone, let\'s... Wait, what is that?',12,0,100.0,0,0,0,109897,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,18,0,'At last we can begin! After the ritual is complete and we have the hammer, the complex will collapse, sealing Tyr\'s resting place forever.',12,0,100.0,0,0,0,109903,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,19,0,'Something is wrong. One of the other Sparks isn\'t here!',12,0,100.0,0,0,0,109904,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106429,20,0,'Wait, I can sense it below, probably taken by one of those monsters. We must have it! We will begin the search when you are ready, champion.',12,0,100.0,0,0,0,109905,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (106447,3,0,'Squires aren\'t normally so quick to train, but I put a rush on this order for ya.',12,0,100.0,1,0,0,122289,0,'LegionCore');
