INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110972,0,0,'Are you here for him? You won\'t get past me!',12,0,100.0,0,0,68337,119468,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110972,1,0,'For ages we hunted the sanctuary known as Netherlight Temple! Hidden, was it, beneath our very noses!',12,0,100.0,0,0,68338,119470,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110972,2,0,'Finally, we sensed it. Holy light, seeping through the Twisting Nether! Blinding us!',12,0,100.0,0,0,68339,119471,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110972,3,0,'Now, our armies will attack, and the Temple will fall... and with it the great Prophet Velen!',12,0,100.0,0,0,68340,119472,0,'LegionCore');
INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES (110972,4,0,'The temple... will.... fall...',12,0,100.0,0,0,68341,119474,0,'LegionCore');
